<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useToast } from 'vue-toastification'
import MasterDataApi, { type EducationalCatalog, type MasterDataRecord } from '@/api/educationalMasterData'
const toast = useToast()
const catalog = ref<EducationalCatalog>('countries'); const rows = ref<MasterDataRecord[]>([]); const countries = ref<MasterDataRecord[]>([]); const dialog = ref(false); const editing = ref<MasterDataRecord | null>(null); const loading = ref(false)
const labels: Record<EducationalCatalog, string> = { countries: 'Countries', 'education-levels': 'Education levels', languages: 'Languages', 'package-types': 'Package types', universities: 'Universities' }
const hasCode = computed(() => ['countries', 'languages'].includes(catalog.value)); const form = ref<Partial<MasterDataRecord>>({ name: '', is_active: true })
async function load() { loading.value = true; try { rows.value = await MasterDataApi.list(catalog.value); countries.value = await MasterDataApi.list('countries') } catch { toast.error('Unable to load master data') } finally { loading.value = false } }
function open(row?: MasterDataRecord) { editing.value = row ?? null; form.value = row ? { ...row } : { name: '', is_active: true }; dialog.value = true }
async function save() { try { if (editing.value) await MasterDataApi.update(catalog.value, editing.value.id, form.value); else await MasterDataApi.create(catalog.value, form.value); dialog.value = false; await load(); toast.success('Saved') } catch (error: any) { toast.error(error.message ?? 'Unable to save') } }
async function remove(row: MasterDataRecord) { if (!confirm(`Remove ${row.name}?`)) return; try { await MasterDataApi.remove(catalog.value, row.id); await load() } catch (error: any) { toast.error(error.message ?? 'This record is in use') } }
watch(catalog, load); onMounted(load)
</script>
<template>
  <VCard><VCardTitle class="d-flex justify-space-between"><span>Educational master data — {{ labels[catalog] }}</span><VBtn prepend-icon="tabler-plus" @click="open()">Add</VBtn></VCardTitle><VCardText><VTabs v-model="catalog"><VTab v-for="(label,key) in labels" :key="key" :value="key">{{ label }}</VTab></VTabs><VProgressLinear v-if="loading" indeterminate class="my-4"/><VTable><thead><tr><th>Name</th><th v-if="hasCode">Code</th><th>Details</th><th>Status</th><th/></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{ row.name }}</td><td v-if="hasCode">{{ row.code }}</td><td>{{ row.city || row.service_type || row.description || '—' }}</td><td><VChip :color="row.is_active ? 'success':'secondary'" size="small">{{ row.is_active?'Active':'Inactive' }}</VChip></td><td><VBtn icon="tabler-pencil" variant="text" @click="open(row)"/><VBtn icon="tabler-trash" variant="text" color="error" @click="remove(row)"/></td></tr></tbody></VTable></VCardText></VCard>
  <VDialog v-model="dialog" max-width="560"><VCard><VCardTitle>{{ editing?'Edit':'Add' }} {{ labels[catalog] }}</VCardTitle><VCardText><VTextField v-model="form.name" label="Name" class="mb-3"/><VTextField v-if="hasCode" v-model="form.code" label="Code" class="mb-3"/><VSelect v-if="catalog==='universities'" v-model="form.country_id" :items="countries.filter(x=>x.is_active).map(x=>({title:x.name,value:x.id}))" label="Country" clearable class="mb-3"/><VTextField v-if="catalog==='universities'" v-model="form.city" label="City" class="mb-3"/><VTextField v-if="catalog==='universities'" v-model="form.website" label="Website" class="mb-3"/><VTextField v-if="catalog==='package-types'" v-model="form.service_type" label="Service type" class="mb-3"/><VTextarea v-if="!hasCode" v-model="form.description" label="Description"/><VSwitch v-model="form.is_active" label="Active"/></VCardText><VCardActions><VSpacer/><VBtn @click="dialog=false">Cancel</VBtn><VBtn color="primary" @click="save">Save</VBtn></VCardActions></VCard></VDialog>
</template>
